import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    evaluated_data = []
    for item in data:
        if isinstance(item, str):
            evaluated_data.append(ast.literal_eval(item))
        else:
            evaluated_data.append(item)
    keys = []
    for d in evaluated_data:
        keys.extend(d.keys())
    return Counter(keys)

